import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.UpdateClientOptions{GraphicsMode: protocol.Option[byte](packet.GraphicsModeRayTraced),
# FilterProfanity: protocol.Option(true)}
BOTH = bytes.fromhex("01030101")

# generated by gophertunnel b8bd735:
# &packet.UpdateClientOptions{}
ABSENT = bytes.fromhex("0000")

# generated by gophertunnel b8bd735:
# &packet.UpdateClientOptions{FilterProfanity: protocol.Option(false)}
UNFILTERED = bytes.fromhex("000100")

GOLDENS = [
    pytest.param(
        v2225.UpdateClientOptionsPacket(graphics_mode=v2225.GraphicsMode.RAY_TRACED, filter_profanity=True),
        BOTH,
        id="both-present",
    ),
    pytest.param(v2225.UpdateClientOptionsPacket(), ABSENT, id="both-absent"),
    pytest.param(
        v2225.UpdateClientOptionsPacket(filter_profanity=False),
        UNFILTERED,
        id="absent-is-not-a-present-false",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168])
def test_update_client_options_is_packet_323(version):
    assert version.PACKETS[323] is version.UpdateClientOptionsPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_client_options_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_client_options_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
